        expected: { path: "/test", params: { path: ["", "test"] } },
      },
      {
        input: "/test/nested",
        expected: {
          path: "/test/nested",
          params: { path: ["", "test", "nested"] },
        },
      },
    ],
  },
  {
    path: "/*path",
    options: { end: false },
    tests: [
      {
        input: "",
        expected: false,
      },
      {
        input: "/",
        expected: false,
      },
      {
        input: "/test",
        expected: { path: "/test", params: { path: ["test"] } },
      },
      {
        input: "/test/nested",
        expected: {
          path: "/test/nested",
          params: { path: ["test", "nested"] },
        },
      },
    ],
  },
  {
    path: "/*path/",
    options: { end: false },
    tests: [
      {
        input: "/foo/bar/",
        expected: { path: "/foo/bar/", params: { path: ["foo", "bar"] } },
      },
      {
        input: "/foo/bar/baz",
        expected: false,
      },
      {
        input: "/foo/bar/baz/",
        expected: {
          path: "/foo/bar/baz/",
          params: { path: ["foo", "bar", "baz"] },
        },
      },
    ],
  },
  {
    path: "/*path.:ext",
    options: { end: false },
    tests: [
      {
        input: "/foo/bar.html",
        expected: {
          path: "/foo/bar.html",
          params: { path: ["foo", "bar"], ext: "html" },
        },
      },
      {
        input: "/foo/bar.html/baz",
        expected: {
          path: "/foo/bar.html",
          params: { path: ["foo", "bar"], ext: "html" },
        },
      },
      {
        input: "/foo/bar.html/baz.html",
        expected: {
          path: "/foo/bar.html/baz.html",
          params: { path: ["foo", "bar.html", "baz"], ext: "html" },
        },
      },
    ],
  },

  /**
   * Longer prefix.
   */
  {
    path: "/:foo{/test/:bar}",
    tests: [
      {
        input: "/route",
        expected: { path: "/route", params: { foo: "route" } },
      },
      {
        input: "/route/test/again",
        expected: {
          path: "/route/test/again",
          params: { foo: "route", bar: "again" },
        },
      },
    ],
  },

  /**
   * Backtracking tests.
   */
  {
    path: "{:foo/}{:bar.}",
    tests: [
      {
        input: "",
        expected: { path: "", params: {} },
      },
      {
        input: "test/",
        expected: {
          path: "test/",
          params: { foo: "test" },
        },
      },
      {
        input: "a/b.",
        expected: { path: "a/b.", params: { foo: "a", bar: "b" } },
      },
    ],
  },
  {
    path: "/abc{abc:foo}",
    tests: [
      {
        input: "/abc",
        expected: { path: "/abc", params: {} },
      },
      {
        input: "/abcabc",
        expected: false,
      },
      {
        input: "/abcabc123",
        expected: { path: "/abcabc123", params: { foo: "123" } },
      },
      {
        input: "/abcabcabc123",
        expected: {
          path: "/abcabcabc123",
          params: { foo: "abc123" },
        },
      },
      {
        input: "/abcabcabc",
        expected: { path: "/abcabcabc", params: { foo: "abc" } },
      },
    ],
  },
  {
    path: "/:foo{abc:bar}",
    tests: [
      {
        input: "/abc",
        expected: {
          params: { foo: "abc" },
          path: "/abc",
        },
      },
      {
        input: "/abcabc",
        expected: {
          params: { foo: "abcabc" },
          path: "/abcabc",
        },
      },
      {
        input: "/abcabc123",
        expected: {
          params: { foo: "abc", bar: "123" },
          path: "/abcabc123",
        },
      },
      {
        input: "/acb",
        expected: {
          path: "/acb",
          params: { foo: "acb" },
        },
      },
      {
        input: "/123",
        expected: {
          path: "/123",
          params: { foo: "123" },
        },
      },
      {
        input: "/123abcabc",
        expected: {
          path: "/123abcabc",
          params: { foo: "123", bar: "abc" },
        },
      },
    ],
  },
  {
    path: "/:foo\\abc:bar",
    tests: [
      {
        input: "/abc",
        expected: false,
      },
      {
        input: "/abcabc",
        expected: false,
      },
      {
        input: "/abcabc123",
        expected: {
          path: "/abcabc123",
          params: { foo: "abc", bar: "123" },
        },
      },
      {
        input: "/123abcabc",
        expected: {
          path: "/123abcabc",
          params: { foo: "123", bar: "abc" },
        },
      },
    ],
  },
  {
    path: "/route|:param|",
    tests: [
      {
        input: "/route|world|",
        expected: {
          path: "/route|world|",
          params: { param: "world" },
        },
      },
      {
        input: "/route||",
        expected: false,
      },
    ],
  },
  {
    path: "/:foo|:bar|",
    tests: [
      {
        input: "/hello|world|",
        expected: {
          path: "/hello|world|",
          params: { foo: "hello", bar: "world" },
        },
      },
      {
        input: "/hello||",
        expected: false,
      },
    ],
  },
  {
    path: "/:foo{|:bar|}",
    tests: [
      {
        input: "/hello|world|",
        expected: {
          path: "/hello|world|",
          params: { foo: "hello", bar: "world" },
        },
      },
      {
        input: "/hello||",
        expected: { path: "/hello||", params: { foo: "hello||" } },
      },
    ],
  },
  {
    path: ":foo\\@:bar",
    tests: [
      {
        input: "x@y",
        expected: { path: "x@y", params: { foo: "x", bar: "y" } },
      },
      {
        input: "x@",
        expected: false,
      },
    ],
  },
  {
    path: "/*foo-:bar",
    tests: [
