// Reproduce: stringify fails to quote param names followed by astral ID_Continue
const { parse, stringify } = require("./src/index.ts");

// Test 1: param followed by astral ID_Continue character \u{1D6FC}
const data1 = parse("/:test");
console.log("Parsed tokens:", JSON.stringify(data1.tokens, null, 2));

// Create token data with astral ID_Continue after param name
const TokenData = parse("/:test").constructor;

// Construct the problematic case manually:
// param name "test" followed by text "\u{1D6FC}" which is ID_Continue
const testTokens = new TokenData([
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
]);

const stringified = stringify(testTokens);
console.log("Stringified:", stringified);
console.log("Expected:   ", '/:"test"\u{1D6FC}');

// Round-trip check
const reParsed = parse(stringified);
console.log("Re-parsed tokens:", JSON.stringify(reParsed.tokens, null, 2));

// Check if round-trip works
const reStringified = stringify(reParsed);
console.log("Re-stringified:", reStringified);
console.log("Round-trip OK:", reStringified === stringified);

// Show the issue: without quotes, the parser absorbs the astral char into the param name
console.log("\n--- Without quotes, what happens ---");
const badPath = "/:test\u{1D6FC}";
const badParsed = parse(badPath);
console.log("Bad parsed:", JSON.stringify(badParsed.tokens, null, 2));

