// Additional edge case tests for the fix
const { parse, stringify } = require("../src/index.ts");

const data = parse("/:test");
const TokenData = data.constructor;

function testRoundTrip(name, tokens, expected) {
  const stringified = stringify(new TokenData(tokens));
  const match = stringified === expected;
  console.log(`${match ? "✅" : "❌"} ${name}: got ${JSON.stringify(stringified)}, expected ${JSON.stringify(expected)}`);

  if (match) {
    const reParsed = parse(stringified);
    const reStringified = stringify(reParsed);
    const roundTripOk = reStringified === stringified;
    console.log(`   Round-trip: ${roundTripOk ? "✅" : "❌"}`);
    if (!roundTripOk) {
      console.log(`   Re-stringified: ${JSON.stringify(reStringified)}`);
    }
  }
}

// Test 1: astral ID_Continue \u{1D6FC} (mathematical italic small alpha)
testRoundTrip("astral ID_Continue \\u{1D6FC}", [
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
], '/:"test"\u{1D6FC}');

// Test 2: astral ID_Continue \u{10330} (Gothic letter ahsa)
testRoundTrip("astral ID_Continue \\u{10330}", [
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{10330}" },
], '/:"test"\u{10330}');

// Test 3: astral non-ID_Continue \u{1F600} (emoji) - should NOT quote
testRoundTrip("astral non-ID_Continue \\u{1F600}", [
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "\u{1F600}" },
], "/:test\u{1F600}");

// Test 4: BMP ID_Continue 'é' - should NOT quote (handled correctly already)
testRoundTrip("BMP ID_Continue é", [
  { type: "text", value: "/" },
  { type: "param", name: "test" },
  { type: "text", value: "é" },
], "/:testé");

// Test 5: no next token - should NOT quote
testRoundTrip("no next token", [
  { type: "text", value: "/" },
  { type: "param", name: "test" },
], "/:test");

// Test 6: next is another param - should NOT quote
testRoundTrip("next is param", [
  { type: "text", value: "/" },
  { type: "param", name: "a" },
  { type: "param", name: "b" },
], "/:a:b");

// Test 7: wildcard followed by astral ID_Continue
testRoundTrip("wildcard + astral ID_Continue", [
  { type: "text", value: "/" },
  { type: "wildcard", name: "test" },
  { type: "text", value: "\u{1D6FC}" },
], '/*"test"\u{1D6FC}');

