// Additional edge case tests for the fix
const { parse, stringify } = require("../src/index.ts");

const data = parse("/:test");
const TokenData = data.constructor;

function testRoundTrip(name, tokens, expected) {
  const stringified = stringify(new TokenData(tokens));
  const match = stringified === expected;
  console.log(`${match ? "✅" : "❌"} ${name}: got ${JSON.stringify(stringified)}, expected ${JSON.stringify(expected)}`);

  if (match) {
    const reParsed = parse(stringified);
    const reStringified = stringify(reParsed);
    const roundTripOk = reStringified === stringified;
    console.log(`   Round-trip: ${roundTripOk ? "✅" : "❌"}`);
    if (!roundTripOk) {
      console.log(`   Re-stringified: ${JSON.stringify(reStringified)}`);
    }
  }
}

